export function validateLocationsResponse(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "locations")) fail(contract, `${path}.locations`, "missing required property");
  if (!Object.hasOwn(record, "unavailable")) fail(contract, `${path}.unavailable`, "missing required property");
  if (!Object.hasOwn(record, "revision")) fail(contract, `${path}.revision`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "locations": {
          if (!Array.isArray(item)) fail(contract, `${path}.locations`, "expected array");
          (item as unknown[]).forEach((item, index) => {
            if (typeof item !== "string") fail(contract, `${`${path}.locations`}[${index}]`, "expected string");
          });
          break;
        }
        case "revision": {
          if (typeof item !== "string") fail(contract, `${path}.revision`, "expected string");
          break;
        }
        case "unavailable": {
          if (!Array.isArray(item)) fail(contract, `${path}.unavailable`, "expected array");
          (item as unknown[]).forEach((item, index) => {
            if (typeof item !== "string") fail(contract, `${`${path}.unavailable`}[${index}]`, "expected string");
          });
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateLockedExecutionSource(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "git")) fail(contract, `${path}.git`, "missing required property");
  if (!Object.hasOwn(record, "ref")) fail(contract, `${path}.ref`, "missing required property");
  if (!Object.hasOwn(record, "path")) fail(contract, `${path}.path`, "missing required property");
  if (!Object.hasOwn(record, "commit")) fail(contract, `${path}.commit`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "commit": {
          if (typeof item !== "string") fail(contract, `${path}.commit`, "expected string");
          break;
        }
        case "git": {
          if (typeof item !== "string") fail(contract, `${path}.git`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.git`, "must contain at least 1 characters");
          if ((item as string).length > 2000) fail(contract, `${path}.git`, "must contain at most 2000 characters");
          break;
        }
        case "kind": {
          if (!(["goon", "plan", "application"] as unknown[]).includes(item)) fail(contract, `${path}.kind`, "was not an allowed enum value");
          if (typeof item !== "string") fail(contract, `${path}.kind`, "expected string");
          break;
        }
        case "path": {
          if (typeof item !== "string") fail(contract, `${path}.path`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.path`, "must contain at least 1 characters");
          if ((item as string).length > 500) fail(contract, `${path}.path`, "must contain at most 500 characters");
          break;
        }
        case "plan": {
          validateUnion(contract, `${path}.plan`, [
            () => {
              if (typeof item !== "string") fail(contract, `${path}.plan`, "expected string");
              if ((item as string).length < 1) fail(contract, `${path}.plan`, "must contain at least 1 characters");
              if ((item as string).length > 500) fail(contract, `${path}.plan`, "must contain at most 500 characters");
            },
            () => {
              if (item !== null) fail(contract, `${path}.plan`, "expected null");
            },
          ]);
          break;
        }
        case "ref": {
          if (typeof item !== "string") fail(contract, `${path}.ref`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.ref`, "must contain at least 1 characters");
          if ((item as string).length > 240) fail(contract, `${path}.ref`, "must contain at most 240 characters");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}
